newtype RiverOutputV1ErrorEnum = RiverOutputV1ErrorEnum
  { riverOutputV1ErrorEnumValue :: Word32
  }
  deriving (Eq, Ord, Show)

-- | invalid presentation mode enum value
pattern RiverOutputV1ErrorEnumInvalidPresentationMode :: RiverOutputV1ErrorEnum
pattern RiverOutputV1ErrorEnumInvalidPresentationMode = RiverOutputV1ErrorEnum 0

-- | Values of @river_output_v1.presentation_mode@.
newtype RiverOutputV1PresentationModeEnum = RiverOutputV1PresentationModeEnum
